                \\ vldmia.f64 r1, { d4 - d7 }
                \\ vstmia.f64 r1!, { d0 - d3 }
                \\ vstmia.f64 r3!, { d4 - d7}
                \\ .endm
                \\ .macro KERNEL_F1
