            else
                "") ++
                \\ cmp r0, #0
                \\ ble 20008f
                \\ cmp r2, #0
                \\ beq 20008f
                \\ cmp r4, #0
                \\ beq 20008f
                \\ cmp r2, #1
                \\ bne 20004f
                \\ cmp r4, #1
                \\ bne 20004f
                \\ 20000:
                \\ asrs r12, r0, #2
                \\ ble 20002f
                \\ .align 5
